import React from 'react';
import { useSelector } from 'react-redux';

interface EulaCheckboxProps {
  checked: boolean;
  onChange: (checked: boolean) => void;
}

const EulaCheckbox: React.FC<EulaCheckboxProps> = ({ checked, onChange }) => {
  const { currentTheme } = useSelector((state: any) => state.UIConfigurations);
  const disabledCheckboxUrl = chrome.runtime.getURL(`assets/images/${currentTheme}/disabled-checkbox.svg`);
  const enabledCheckboxUrl = chrome.runtime.getURL('assets/images/enabled-checkbox.svg');

  return (
    <span
      className={`eula-checkbox ${checked ? 'checked' : 'unchecked'}`}
      style={{ backgroundImage: `url(${checked ? enabledCheckboxUrl : disabledCheckboxUrl})` }}
      onClick={() => onChange(!checked)}
      role="checkbox"
      aria-checked={checked}
      tabIndex={0}
      onKeyDown={e => (e.key === ' ' || e.key === 'Enter') && onChange(!checked)}
    />
  );
};

export default EulaCheckbox;
