import React, { useState } from 'react';
import EulaContinueButton from './EulaContinueButton';
import EulaCheckbox from './EulaCheckbox';
import '../common/styles/eulaPopup.scss';
import { EULA_LINKS, REDUX_ACTIONS, VERSION_PLACEHOLDER, MESSAGE_TYPES, BRAND_NAME } from '../../constants';
import { useDispatch, useSelector } from 'react-redux';
import { isRtlEnvironment } from '../../utils/LocaleUtils';

const strings = {
    eulaHeading: chrome.i18n.getMessage('eulaHeading'),
    eulaConfirmation: chrome.i18n.getMessage('eulaConfirmation'),
    closeText: chrome.i18n.getMessage('closeText')
};

const EulaPopup: React.FC = () => {
  const [checked, setChecked] = useState(false);
  const dispatch = useDispatch();
  // Listen to eulaDismissed from Redux store
  const eulaDismissed = useSelector((state: any) => state.eulaAcceptanceDetails?.eulaDismissed);
  const browserVersion = useSelector((state: any) => state.UIConfigurations?.browserVersion);
  const browserBrand = useSelector((state: any) => state.UIConfigurations?.browserBrand);
  const { currentTheme } = useSelector((state: any) => state.UIConfigurations);
  const [visible, setVisible] = useState(true);
  // Determine RTL just once per render
  const isRtl = isRtlEnvironment();
  const closeIconUrl = chrome.runtime.getURL(`assets/images/${currentTheme}/plain-cross.svg`);
  const infoIconUrl = chrome.runtime.getURL('assets/images/status_info.svg');


  // Hide popup if eulaDismissed becomes true in any tab
  React.useEffect(() => {
    if (eulaDismissed) setVisible(false);
  }, [eulaDismissed]);

  React.useEffect(()=> {
    document.documentElement.setAttribute('data-gen-theme', currentTheme);
  },[]);

  const getEulaDescription = () => {
    const brandBasedEulaLink = browserBrand && EULA_LINKS[browserBrand as keyof typeof EULA_LINKS] 
      ? EULA_LINKS[browserBrand as keyof typeof EULA_LINKS] : '';
    
    const eulaLinkWithParams = brandBasedEulaLink ? `${brandBasedEulaLink}?click_source=vd&browser_version=${browserVersion}`: '';
    let eulaText = chrome.i18n.getMessage('eulaDescription', [eulaLinkWithParams]);
    return eulaText;
  };

  const handleContinue = () => {
    chrome.runtime.sendMessage({ 
      type: MESSAGE_TYPES.EULA_ACCEPTED
    });
    setVisible(false);
  };

  const handleClose = () => {
    chrome.runtime.sendMessage({ 
      type: MESSAGE_TYPES.EULA_DISMISSED
    });
    setVisible(false);
  };

  if (!visible) return null;

  return (
    <div className={`eula-popup-center${isRtl ? ' rtl' : ''}`}>
      <div className="eula-popup-overlay">
        <div className="eula-popup">
          <div className="eula-popup-header">
            <img src={infoIconUrl} className="eula-popup-info-icon" alt="Info" />
            <span className="eula-popup-title">{strings.eulaHeading}</span>
            <img src={closeIconUrl} className="eula-popup-close" onClick={handleClose} title={strings.closeText} alt={strings.closeText} />
          </div>
          <div className="eula-popup-content">
            <div className="eula-popup-text" dangerouslySetInnerHTML={{ __html: getEulaDescription() }} />
          </div>
          <div className="eula-popup-actions">
            <EulaCheckbox checked={checked} onChange={setChecked} />
            <span className="eula-popup-checkbox-label">{strings.eulaConfirmation}</span>
            <EulaContinueButton enabled={checked} onClick={handleContinue} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default EulaPopup;
