import React from 'react';
import * as ReactDOM from 'react-dom/client';
import { Provider } from 'react-redux';
import { Store } from 'webext-redux';
import { VIDEO_DOWNLOADER_GLOBAL_POPUP_ROOT_ID } from './constants';
import EulaPopup from './ui/components/EulaPopup';
import { localStore } from './utils/storageManager';
import { UiUtils } from './utils/UiUtils';
import { FontFaceInjector } from './utils/FontFaceInjector';
import './ui/common/styles/eulaPopup.scss';


/**
 * EulaPopupCS - Script that manages EULA popup display
 * This is injected using chrome.scripting.executeScript when a download is
 * requested on any URL and EULA needs to be shown.
 */
class EulaPopupCS {
  private proxyStore: Store;
  private isInitialized = false;
  private eulaRootContainer: HTMLDivElement | null = null;
  private eulaReactRoot: ReactDOM.Root | null = null;

  constructor() {
    this.handleMessages = this.handleMessages.bind(this);
    this.initializeStore = this.initializeStore.bind(this);
    this.showEulaPopup = this.showEulaPopup.bind(this);
  }

  /**
   * Initialize the Redux store and connect to it
   */
  async initializeStore(): Promise<void> {
    if (this.isInitialized) {
      return;
    }

    this.proxyStore = new Store();
    await this.proxyStore.ready();
    this.isInitialized = true;
  }

  /**
   * Unmount and remove any existing React root and DOM node for the EULA popup
   * This is the single cleanup function to be used everywhere.
   */
  private cleanupEulaRoot(): void {
    const existingRoot = document.getElementById(VIDEO_DOWNLOADER_GLOBAL_POPUP_ROOT_ID);
    if (existingRoot) {
      if ((existingRoot as any).__reactRoot) {
        try {
          (existingRoot as any).__reactRoot.unmount();
        } catch (e) {
          // Ignore errors
        }
        (existingRoot as any).__reactRoot = null;
      }
      existingRoot.parentNode?.removeChild(existingRoot);
    }
    this.eulaRootContainer = null;
    this.eulaReactRoot = null;
  }

  /**
   * Create the DOM element for the EULA popup and render it
   * Always cleans up any previous root and DOM node to prevent React error #300
   */
  createEulaRootElement(): void {
    // Always inject Roboto font-face using UiUtils (unified logic)
    FontFaceInjector.injectFontFace();
    // Remove any existing root and DOM node first
    this.cleanupEulaRoot();
    // Now create a new root node
    this.eulaRootContainer = document.createElement('div');
    this.eulaRootContainer.id = VIDEO_DOWNLOADER_GLOBAL_POPUP_ROOT_ID;
    document.body.appendChild(this.eulaRootContainer);
  }

  /**
   * Show the EULA popup and render the React component
   * Always shows when called; cross-tab dismissal is handled by store subscription
   */
  async showEulaPopup(): Promise<void> {
    this.createEulaRootElement();
    if (this.eulaRootContainer) {
      try {
        this.eulaReactRoot = ReactDOM.createRoot(this.eulaRootContainer);
        (this.eulaRootContainer as any).__reactRoot = this.eulaReactRoot;
        this.eulaReactRoot.render(
          <Provider store={this.proxyStore}>
            <EulaPopup />
          </Provider>
        );
      } catch (error) {
        // Error rendering EULA popup
      }
    }
  }

  /**
   * Handle incoming messages from background script or other content scripts
   * Only legacy support for hiding the popup
   */
  async handleMessages(message: any, sender: chrome.runtime.MessageSender, sendResponse: (response?: any) => void): Promise<boolean> {
    if (!message) {
       return false;
    }
    return false;
  }

  /**
   * Initialize the script
   * Always show the popup
   */
  async init(): Promise<void> {
    await this.initializeStore();
    this.showEulaPopup();
    chrome.runtime.onMessage.addListener(this.handleMessages);
  }

  /**
   * Set up DOMContentLoaded listener and initialize the EULA popup script
   */
  static initListener() {
    const eulaPopupCS = new EulaPopupCS();
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', async () => {
        await eulaPopupCS.init();
      });
    } else {
      eulaPopupCS.init();
    }
  }
}
EulaPopupCS.initListener();
