import React from 'react';

interface EulaContinueButtonProps {
  enabled: boolean;
  onClick: () => void;
}
const strings = {
    continue: chrome.i18n.getMessage('continue')
  };

const EulaContinueButton: React.FC<EulaContinueButtonProps> = ({ enabled, onClick }) => {
  return (
    <button
      type="button"
      className={`eula-continue-btn${enabled ? ' enabled' : ''}`}
      onClick={enabled ? onClick : undefined}
      disabled={!enabled}
    >
      {strings.continue}
    </button>
  );
};

export default EulaContinueButton;