
/**
 * Utility to inject Roboto font-face rules into the document head if not already present.
 * Can be used by both Player UI and EULA popup for consistent font loading.
 */
export class FontFaceInjector {
  static injectFontFace(): void {
    if (document.getElementById('video-downloader-roboto-font-face')) return;
    const regularFontUrl = chrome.runtime.getURL('assets/fonts/Roboto-Regular.ttf');
    const mediumFontUrl = chrome.runtime.getURL('assets/fonts/Roboto-Medium.ttf');
    const boldFontUrl = chrome.runtime.getURL('assets/fonts/Roboto-Bold.ttf');
    const mierFontUrl = chrome.runtime.getURL('assets/fonts/MierB03-Regular.ttf');
    const style = document.createElement('style');
    style.id = 'video-downloader-roboto-font-face';
    style.textContent = `
      @font-face {
        font-family: 'Roboto Regular';
        src: url('${regularFontUrl}') format('truetype');
        font-weight: 400;
        font-style: normal;
      }
      @font-face {
        font-family: 'Roboto Medium';
        src: url('${mediumFontUrl}') format('truetype');
        font-weight: 500;
        font-style: normal;
      }
      @font-face {
        font-family: 'Roboto Bold';
        src: url('${boldFontUrl}') format('truetype');
        font-weight: 700;
        font-style: normal;
      }
       @font-face {
        font-family: 'Mier B03 Pan';
        src: url('${mierFontUrl}') format('truetype');
        font-weight: 400;
        font-style: normal;
      }
    `;
    document.head.appendChild(style);
  }
}

export default FontFaceInjector;
